parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const alertType = data.alertType || data.type || 'general';
  const message = data.message || data.text || 'Alert triggered';
  const recipient = data.phone || data.to || '';
  const priority = data.priority || 'normal';
  const truncated = message.length > 140 ? message.substring(0, 137) + '...' : message;
  return {
    json: {
      to: recipient,
      alertType: alertType,
      message: truncated,
      fullMessage: message,
      priority: priority,
      timestamp: new Date().toISOString(),
      smsBody: `[${alertType.toUpperCase()}] ${truncated}`
    }
  };
});

